local script=debug.getinfo(1,'S').source:sub(2);local dir=script:match('^(.*)[/\\]');package.path=dir..'/?.lua;'..package.path
local b=require('_bootstrap');local a=b.lib('args');local o=a.parse(arg);local path=b.lib('path');local process=b.lib('process');local evidence=b.lib('evidence');local root=path.absolute(a.required(o,'evidence-dir'));path.mkdir_p(root)
